import sys

def main():
    stdin = sys.stdin.buffer
    header = stdin.readline()
    if not header:
        return
    sums = {}
    for line in stdin:
        line = line.strip()
        if not line:
            continue
        c1 = line.find(b',')
        c2 = line.find(b',', c1 + 1)
        cat = line[c1 + 1:c2]
        val = float(line[c2 + 1:])
        sums[cat] = sums.get(cat, 0.0) + val

    out = sys.stdout.buffer
    for cat in sorted(sums):
        out.write(cat + b',' + f"{sums[cat]:.2f}\n".encode('ascii'))

if __name__ == '__main__':
    main()

import sys

def main():
    try:
        import ctypes
        if ctypes.CDLL("./_csvsum.so").process_stdin() == 0:
            return
    except Exception:
        pass

    stdin = sys.stdin.buffer
    if not stdin.readline():
        return
    sums = {}
    float_ = float
    for line in stdin:
        try:
            _, cat, val_str = line.split(b',')
            sums[cat] += float_(val_str)
        except KeyError:
            sums[cat] = float_(val_str)
        except ValueError:
            pass

    sys.stdout.buffer.write(b''.join(cat + b',' + f"{sums[cat]:.2f}\n".encode('ascii') for cat in sorted(sums)))

if __name__ == '__main__':
    main()

